class Solution {
public:
    string reverseWords(string s) {
        int n = s.size(), start = 0;
        while (start < n) {
            int end = start;
            while (end < n && s[end] != ' ') end++;
            int l = start, r = end - 1;
            while (l < r) swap(s[l++], s[r--]);
            start = end + 1;
        }
        return s;
    }
};
